import { SegmentedControl } from '@kerfjs/ui/segmented-control';
import '@kerfjs/ui/layout.css';

export type WorkspaceView = 'board' | 'list' | 'timeline';
export type WorkspaceAction = { type: 'workspace.view.change'; view: WorkspaceView };
const options = [{value:'board', label:'Board'}, {value:'list', label:'List'}, {value:'timeline', label:'Timeline'}];
export function WorkspaceViewChoice({value, dispatch}: {value: WorkspaceView; dispatch: (action: WorkspaceAction) => void}) {
  return <SegmentedControl aria-label="Workspace view" value={value} options={options} onValueChange={(next: string) => {
    if ((next === 'board' || next === 'list' || next === 'timeline') && next !== value) {
      dispatch({type:'workspace.view.change', view:next});
    }
  }}/>;
}
// Place this controlled choice inside the application's Toolbar. The component
// owns its exclusive-choice keyboard interaction; the application owns the value.
